	@Inject
	public RequirementsModelGrammarAccess(GrammarProvider grammarProvider,
			TerminalsGrammarAccess gaTerminals) {
		this.grammar = internalFindGrammar(grammarProvider);
		this.gaTerminals = gaTerminals;
		this.pRequirementsModel = new RequirementsModelElements();
		this.pRequirement = new RequirementElements();
		this.eQualityAttribute = new QualityAttributeElements();
		this.eMathOperator = new MathOperatorElements();
		this.pCondition = new ConditionElements();
		this.eLogicalOperator = new LogicalOperatorElements();
		this.pProposition = new PropositionElements();
		this.pStatement = new StatementElements();
		this.pAsCloseFreq = new AsCloseFreqElements();
		this.pAsCloseLit = new AsCloseLitElements();
		this.pQuantifiable = new QuantifiableElements();
		this.pMayStatement = new MayStatementElements();
		this.pAtomicStatement = new AtomicStatementElements();
		this.pEvent = new EventElements();
		this.pTimeInterval = new TimeIntervalElements();
		this.pTime = new TimeElements();
		this.pLiteral = new LiteralElements();
		this.pIntLiteral = new IntLiteralElements();
		this.pDecimalLiteral = new DecimalLiteralElements();
		this.pStringLiteral = new StringLiteralElements();
		this.pBooleanLiteral = new BooleanLiteralElements();
		this.tDECIMAL = (TerminalRule) GrammarUtil.findRuleForName(getGrammar(), "eu.coresense.requirements.RequirementsModel.DECIMAL");
		this.tBOOLEAN = (TerminalRule) GrammarUtil.findRuleForName(getGrammar(), "eu.coresense.requirements.RequirementsModel.BOOLEAN");
	}
	
	protected Grammar internalFindGrammar(GrammarProvider grammarProvider) {
		Grammar grammar = grammarProvider.getGrammar(this);
		while (grammar != null) {
			if ("eu.coresense.requirements.RequirementsModel".equals(grammar.getName())) {
				return grammar;
			}
			List<Grammar> grammars = grammar.getUsedGrammars();
			if (!grammars.isEmpty()) {
				grammar = grammars.iterator().next();
			} else {
				return null;
			}
		}
		return grammar;
	}
	
	@Override
	public Grammar getGrammar() {
		return grammar;
	}
	
	
